export async function sendMail(to: string, subject: string, body: string, key: string): Promise<void> {
  try {
    await new EmailProviderClient().sendEmail({ to: to, subject: subject, body: body, idempotencyKey: key });
  }
  catch (__caught: unknown) {
    {
      const e = __caught as Error;
      console.warn('email_not_sent');
    }
  }
}

/**
 * The lender's answer, in the buyer's name. A refusal stops the offer here.
 */
export async function lenderReferenceFor(request: MakeOffer, buyerName: string, buyerEmail: string): Promise<string> {
  const answer: Preapproval = await new MortgageProviderClient().preapprove({ applicantName: buyerName, applicantEmail: buyerEmail, amount: request.amount, idempotencyKey: `offer-${request.listingId}-${buyerEmail}-${_decimalText(request.amount)}` });
  if ((answer.decision === PreapprovalDecision.Declined)) {
    throw new LenderDeclinedError({});
  }
  return answer.reference;
}

/**
 * Standalone version of ownAsAgent for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function ownAsAgent(id: string, em: EntityManager): Promise<Offer> {
  const offer = await em.getRepository(Offer).findOne({ id: id });
  if (!offer) {
    throw new NotFoundException("Not found");
  }
  if ((String(offer.agentEmail) !== String((currentUserIdentity().email as string)))) {
    throw new NotYourOfferError({});
  }
  return offer;
}

